changeSet.sql:
UPDATE public.product
SET segment_type = 'MSB', updated_date = now()
WHERE lower(trim(name)) IN (lower('Бизнес Лимит'), lower('Онлайн кредит ИП'));

DO $$ DECLARE r RECORD; new_id BIGINT; BEGIN FOR r IN SELECT sf.*, COALESCE(sf.root_id, sf.id) AS factor_id FROM stop_factors.stop_factor sf WHERE sf.valid_to IS NULL AND (COALESCE(sf.root_id, sf.id) IN (11, 12) OR (COALESCE(sf.root_id, sf.id) BETWEEN 17 AND 34 AND sf.is_active)) ORDER BY factor_id FOR UPDATE LOOP -- the current version is closed first: only one current version per stop factor (ux_stop_factor_current_version) UPDATE stop_factors.stop_factor SET valid_to = now() WHERE id = r.id;
new_id := nextval('stop_factors.stop_factor_id_generator'); INSERT INTO stop_factors.stop_factor (id, created_date, name, description, is_active, order_number, root_id, version_number, valid_from, change_reason, created_by, metric_id, params, segment) VALUES (new_id, now(), r.name, r.description, r.factor_id IN (11, 12) AND r.is_active, r.order_number, r.factor_id, r.version_number + 1, now(), CASE WHEN r.factor_id IN (11, 12) THEN 'Новые общие ограничения 2026' ELSE 'Заменен правилами по просрочкам для Розницы и МСБ 2026' END, 'migration', r.metric_id, r.params, r.segment);
INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result) SELECT nextval('stop_factors.stop_factor_condition_id_generator'), now(), new_id, CASE WHEN c.result = 'REJECTED' AND r.factor_id = 11 THEN '3' WHEN c.result = 'REJECTED' AND r.factor_id = 12 THEN '7' ELSE c.value END, c.value_type, c.result FROM stop_factors.stop_factor_condition c WHERE c.stop_factor_id = r.id;
INSERT INTO stop_factors.stop_factor_product (stop_factor_id, product_id) SELECT new_id, product_id FROM stop_factors.stop_factor_product WHERE stop_factor_id = r.id; END LOOP;
-- #11 and #12 had a REJECTED condition, otherwise the new limits were not applied IF (SELECT count(*) FROM stop_factors.stop_factor sf JOIN stop_factors.stop_factor_condition c ON c.stop_factor_id = sf.id AND c.result = 'REJECTED' WHERE sf.valid_to IS NULL AND ((COALESCE(sf.root_id, sf.id) = 11 AND c.value = '3') OR (COALESCE(sf.root_id, sf.id) = 12 AND c.value = '7'))) <> 2 THEN RAISE EXCEPTION 'Stop factors 11 and 12 must have a REJECTED condition to get the 2026 limits'; END IF; END $$;

rollback.sql:
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT id, root_id, valid_from FROM stop_factors.stop_factor
        WHERE created_by = 'migration' AND valid_to IS NULL
          AND change_reason IN ('Новые общие ограничения 2026', 'Заменен правилами по просрочкам для Розницы и МСБ 2026')
    LOOP
        DELETE FROM stop_factors.stop_factor_condition WHERE stop_factor_id = r.id;
        DELETE FROM stop_factors.stop_factor_product WHERE stop_factor_id = r.id;
        DELETE FROM stop_factors.stop_factor WHERE id = r.id;
        UPDATE stop_factors.stop_factor SET valid_to = NULL
        WHERE COALESCE(root_id, id) = r.root_id AND valid_to = r.valid_from;
    END LOOP;
END $$;

changeSet.sql:
DO $$ DECLARE metric BIGINT; next_order INT; r RECORD; sf_id BIGINT; BEGIN SELECT id INTO metric FROM stop_factors.stop_factor_metric WHERE calculator = 'OVERDUE_BUCKET_COUNT' ORDER BY id LIMIT 1; IF metric IS NULL THEN RAISE EXCEPTION 'Metric OVERDUE_BUCKET_COUNT not found'; END IF; SELECT COALESCE(MAX(order_number), 0) INTO next_order FROM stop_factors.stop_factor WHERE valid_to IS NULL;
FOR r IN SELECT * FROM (VALUES -- months overdue days UNDERWRITER REJECTED ( 1, 'RETAIL', 1, 3, 1, 10::int, NULL::int, 5), ( 2, 'RETAIL', 1, 3, 11, 20, 1, 2), ( 3, 'RETAIL', 1, 3, 21, NULL, NULL, 0), ( 4, 'RETAIL', 4, 6, 1, 10, NULL, 5), ( 5, 'RETAIL', 4, 6, 11, 20, 1, 2), ( 6, 'RETAIL', 4, 6, 21, NULL, NULL, 0), ( 7, 'RETAIL', 7, 12, 6, 10, 5, 8), ( 8, 'RETAIL', 7, 12, 11, 20, 0, 1), ( 9, 'RETAIL', 7, 12, 21, NULL, NULL, 0), (10, 'RETAIL', 13, 24, 11, 20, 7, 10), (11, 'RETAIL', 13, 24, 21, 30, 0, 1), (12, 'RETAIL', 13, 24, 31, NULL, NULL, 0), (13, 'RETAIL', 25, 36, 31, 60, 0, 1), (14, 'RETAIL', 25, 36, 61, NULL, NULL, 0), (15, 'MSB', 1, 3, 1, 10, 5, 10), (16, 'MSB', 1, 3, 11, 20, 1, 2), (17, 'MSB', 1, 3, 21, NULL, NULL, 0), (18, 'MSB', 4, 6, 1, 10, 5, 10), (19, 'MSB', 4, 6, 11, 20, 1, 2), (20, 'MSB', 4, 6, 21, NULL, NULL, 0), (21, 'MSB', 7, 12, 11, 20, 7, 10), (22, 'MSB', 7, 12, 21, 30, 0, 1), (23, 'MSB', 7, 12, 31, NULL, NULL, 0), (24, 'MSB', 13, 24, 11, 20, 7, 10), (25, 'MSB', 13, 24, 21, 30, 0, 1), (26, 'MSB', 13, 24, 31, NULL, NULL, 0), (27, 'MSB', 25, 36, 31, 60, 0, 1), (28, 'MSB', 25, 36, 61, NULL, NULL, 0) ) AS t(n, segment, period_from, period_to, min_days, max_days, underwriter_above, rejected_above) ORDER BY n LOOP sf_id := nextval('stop_factors.stop_factor_id_generator'); next_order := next_order + 1;
-- the name is the metric's name template rendered with the params, as the console does INSERT INTO stop_factors.stop_factor (id, created_date, name, description, is_active, order_number, version_number, valid_from, change_reason, created_by, metric_id, params, segment) VALUES (sf_id, now(), format('Количество непрерывной просроченной задолженности по основному долгу и/или процентам с %s по %s месяц, где максимальная просрочка >= %s', r.period_from, r.period_to, r.min_days) || CASE WHEN r.max_days IS NOT NULL THEN ' и <= ' || r.max_days ELSE '' END, CASE r.segment WHEN 'RETAIL' THEN 'Розница и ИФЦ' ELSE 'МСБ' END, true, next_order, 1, now(), 'Правила по просрочкам 2026', 'migration', metric, jsonb_strip_nulls(jsonb_build_object( 'periodFromMonth', r.period_from, 'periodToMonth', r.period_to, 'minOverdueDays', r.min_days, 'maxOverdueDays', r.max_days)), r.segment);
INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result) VALUES (nextval('stop_factors.stop_factor_condition_id_generator'), now(), sf_id, r.rejected_above::text, 'INTEGER', 'REJECTED');
IF r.underwriter_above IS NOT NULL THEN INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, value, value_type, result) VALUES (nextval('stop_factors.stop_factor_condition_id_generator'), now(), sf_id, r.underwriter_above::text, 'INTEGER', 'UNDERWRITER'); END IF; END LOOP; END $$;

rollback.sql:
DELETE FROM stop_factors.stop_factor_condition
WHERE stop_factor_id IN (SELECT id FROM stop_factors.stop_factor
                         WHERE created_by = 'migration' AND change_reason = 'Правила по просрочкам 2026');
DELETE FROM stop_factors.stop_factor
WHERE created_by = 'migration' AND change_reason = 'Правила по просрочкам 2026';
